'use strict';

const assert = require('node:assert/strict');
const path = require('node:path');
const test = require('node:test');
const { ConfigCache } = require('../src/config-cache');
const { createConfigLoader } = require('../src/config-loader');
const { readProfile } = require('../src/profile-source');

const workspaceRoot = (name) => path.join(__dirname, '..', 'workspaces', name);

test('loads file values and applies numeric environment and request overrides', () => {
  const loader = createConfigLoader();

  const config = loader.load({
    rootDir: workspaceRoot('alpha'),
    env: { APP_PORT: '7410' },
    overrides: { timeoutMs: 4200 }
  });

  assert.equal(config.serviceName, 'alpha-api');
  assert.equal(config.region, 'eu-central');
  assert.equal(config.port, 7410);
  assert.equal(config.timeoutMs, 4200);
});

test('does not reuse one workspace profile for another workspace', () => {
  const cache = new ConfigCache();
  const loader = createConfigLoader({ cache });

  const alpha = loader.load({ rootDir: workspaceRoot('alpha') });
  const beta = loader.load({ rootDir: workspaceRoot('beta') });

  assert.equal(alpha.serviceName, 'alpha-api');
  assert.equal(beta.serviceName, 'beta-api');
  assert.equal(beta.region, 'us-east');
  assert.equal(beta.port, 7202);
  assert.equal(cache.size(), 2);
});

test('reuses the base while evaluating per-call environment overlays', () => {
  const cache = new ConfigCache();
  let reads = 0;
  const loader = createConfigLoader({
    cache,
    readProfileFn: (...args) => {
      reads += 1;
      return readProfile(...args);
    }
  });

  const first = loader.load({
    rootDir: workspaceRoot('gamma'),
    env: { APP_REGION: 'first-region' }
  });
  const second = loader.load({
    rootDir: workspaceRoot('gamma'),
    env: { APP_REGION: 'second-region' },
    overrides: { timeoutMs: 9999 }
  });

  assert.equal(first.region, 'first-region');
  assert.equal(second.region, 'second-region');
  assert.equal(second.timeoutMs, 9999);
  assert.equal(reads, 1);
  assert.equal(cache.size(), 1);
});
'use strict';

const { DEFAULT_CONFIG } = require('./default-config');
const { ConfigCache } = require('./config-cache');
const { parseEnv } = require('./env-overrides');
const { readProfile } = require('./profile-source');

function createConfigLoader({ cache = new ConfigCache(), readProfileFn = readProfile } = {}) {
  function load({ rootDir, profile = 'development', env = {}, overrides = {} } = {}) {
    if (!rootDir) {
      throw new Error('rootDir is required');
    }

    // BUG: profile alone is not a stable identity when multiple workspaces share a cache.
    const cacheKey = profile;
    let base = cache.get(cacheKey);

    if (base === undefined) {
      const fileConfig = readProfileFn(rootDir, profile);
      base = { ...DEFAULT_CONFIG, ...fileConfig };
      cache.set(cacheKey, base);
    }

    return {
      ...base,
      ...parseEnv(env),
      ...overrides
    };
  }

  return { load, cache };
}

module.exports = { createConfigLoader };

'use strict';

class ConfigCache {
  constructor() {
    this.entries = new Map();
  }

  get(key) {
    return this.entries.get(key);
  }

  set(key, value) {
    const stored = Object.freeze({ ...value });
    this.entries.set(key, stored);
    return stored;
  }

  size() {
    return this.entries.size;
  }
}

module.exports = { ConfigCache };
'use strict';

const fs = require('node:fs');
const path = require('node:path');

function readProfile(rootDir, profile) {
  const profilePath = path.join(rootDir, 'config', `${profile}.json`);
  return JSON.parse(fs.readFileSync(profilePath, 'utf8'));
}

module.exports = { readProfile };
'use strict';

function parsePositiveInteger(name, value) {
  const parsed = Number(value);
  if (!Number.isInteger(parsed) || parsed <= 0) {
    throw new Error(`${name} must be a positive integer`);
  }
  return parsed;
}

function parseEnv(env) {
  const overrides = {};

  if (env.APP_SERVICE_NAME !== undefined) {
    overrides.serviceName = String(env.APP_SERVICE_NAME);
  }
  if (env.APP_REGION !== undefined) {
    overrides.region = String(env.APP_REGION);
  }
  if (env.APP_PORT !== undefined) {
    overrides.port = parsePositiveInteger('APP_PORT', env.APP_PORT);
  }
  if (env.APP_TIMEOUT_MS !== undefined) {
    overrides.timeoutMs = parsePositiveInteger('APP_TIMEOUT_MS', env.APP_TIMEOUT_MS);
  }

  return overrides;
}

module.exports = { parseEnv };
